import test from 'node:test';
import assert from 'node:assert/strict';
import { createLiveEditorialCycle, evaluateKoreaDailyReadiness } from '../src/editorial/live-cycle.js';
const cycle = () => createLiveEditorialCycle();
test('live cycle uses latest independently completed category dates', () => { const run = cycle(); assert.equal(run.units.find(x => x.category === 'AI_INTELLIGENCE')?.issueDate, '2026-10-05'); assert.equal(run.units.find(x => x.category === 'US_MARKET')?.issueDate, '2026-10-05'); assert.equal(run.units.find(x => x.category === 'KOREA_MARKET')?.issueDate, '2026-10-06'); });
test('AI plan has three verified-depth candidates and no duplicate selection', () => { const unit = cycle().units.find(x => x.category === 'AI_INTELLIGENCE'); assert.equal(unit.itemCount, 3); assert.equal(unit.plan.contentDepthGate, 'PASS'); assert.ok(unit.plan.selected.every(item => item.sourceRefs.length && Object.values(item.depth).every(Boolean))); assert.equal(unit.plan.selected.some(item => item.coverageState === 'DUPLICATE'), false); });
test('US render retains four actual five-session charts without duplicate chart cards', () => { const unit = cycle().units.find(x => x.category === 'US_MARKET'); assert.equal((unit.render.html.match(/<svg\b/g) ?? []).length, 4); assert.equal((unit.render.html.match(/data-layout="responsive-two-by-two"/g) ?? []).length, 1); assert.match(unit.render.html, /7,773\.95|7773\.95/); assert.match(unit.render.html, /5\.31%/); });
test('Korea brokerage research is optional when required market facts and explanation pass', () => { const unit = cycle().units.find(x => x.category === 'KOREA_MARKET'); assert.equal(unit.publicationReadiness, 'APPROVAL_REQUIRED'); assert.equal(unit.plan.reviewState, 'APPROVAL_REQUIRED'); assert.ok(unit.warnings.includes('BROKERAGE_RESEARCH_NOT_AVAILABLE')); assert.doesNotMatch(unit.render.html, /목표주가|투자의견/); assert.equal(unit.viewModel.marketHistory, undefined); });
test('Korea required facts gate blocks a missing index without creating fake history', () => { const view = structuredClone(cycle().units.find(x => x.category === 'KOREA_MARKET').viewModel); view.indexMetrics = view.indexMetrics.filter(item => item.label !== 'KOSDAQ'); const result = evaluateKoreaDailyReadiness(view); assert.equal(result.ready, false); assert.ok(result.blockers.includes('VERIFIED_KOSDAQ_REQUIRED')); assert.equal(view.marketHistory, undefined); });
test('US chart caption uses actual input dates and rejects stale issue mixing', () => { const html = cycle().units.find(x => x.category === 'US_MARKET').render.html; assert.match(html, /2026년 9월 29일~10월 5일 정규장 종가/); assert.doesNotMatch(html, /2026년 9월 10~16일 정규장 종가/); });
test('cycle has no external action, fake search metric, PDF distribution, or Commerce', () => { const run = cycle(); assert.deepEqual(run.externalActions, { bloggerLookup: 0, bloggerInsert: 0, bloggerPatch: 0, bloggerPublish: 0 }); assert.equal(run.searchMetricsStatus, 'NOT_AVAILABLE'); assert.equal(run.pdfStatus, 'NOT_GENERATED'); assert.equal(run.commerce.enabled, false); });
test('editorial memories are retrieved and every new candidate remains review required', () => { const run = cycle(); assert.ok(run.retrievedMemoryCount >= 7); assert.ok(run.newMemoryCandidates.length); assert.ok(run.newMemoryCandidates.every(item => item.reviewState === 'REVIEW_REQUIRED')); });
